sys_script_include.script:
var CLMApprovalLimit = Class.create();
CLMApprovalLimit.prototype = {
    initialize: function() {},

    FIELD: 'u_approval_limits',

    save: function(requestSysId, approvalSysId, limit) {
        var n = parseFloat(limit);
        if (!requestSysId || !approvalSysId || isNaN(n)) return;

        var rq = new GlideRecord('x_birl3_clm_clm_new_credit_request');
        if (!rq.get(requestSysId)) return;

        var map = {};
        try { map = JSON.parse(rq.getValue(this.FIELD) || '{}'); } catch (e) { map = {}; }
        map[approvalSysId] = n;

        rq.setValue(this.FIELD, JSON.stringify(map));
        rq.setWorkflow(false);
        rq.autoSysFields(false);
        rq.update();
    },

    type: 'CLMApprovalLimit'
};
